def init_agent():
    return {'known': jnp.full((9,), -1, jnp.int32), 'positions': jnp.zeros((9,2),jnp.int32), 'motion': jnp.zeros((1680,),jnp.float32)}


def beliefs(obs, known, motion):
    COLORS = jnp.asarray(COLOR_DATA, jnp.int32)
    ONEHOT = jax.nn.one_hot(COLORS, 3)
    SAME = (COLORS[:, :, None] == COLORS[:, None, :]).astype(jnp.float32)
    f = obs.node_features
    visible = jnp.sum(f[:9, :3], -1) > 0
    known = jnp.where(visible, jnp.argmax(f[:9, :3], -1), known)
    consistent = jnp.all((known[None, :] < 0) | (COLORS == known[None, :]), -1)
    # Hints are usually truthful, but cannot override personally seen colors.
    hintsets = f[9:, 3:6]
    attached = obs.adjacency_matrix[9:, :9].astype(jnp.float32)
    allowed = jnp.einsum('hi,hc->ic', attached, hintsets)
    hinted = jnp.sum(attached, 0) > 0
    matches = jnp.sum(ONEHOT * allowed[None, :, :], -1) > 0
    likelihood = jnp.prod(jnp.where(hinted[None, :], jnp.where(matches, 1., .01), 1.), -1)
    weights = consistent * likelihood * jnp.exp(motion)
    weights = weights / jnp.maximum(jnp.sum(weights), 1e-20)
    probs = jnp.einsum('s,sic->ic', weights, ONEHOT)
    pair = jnp.einsum('s,sij->ij', weights, SAME)
    return known, weights, probs, pair


def geometry(pos, locks):
    cells = jnp.stack([jnp.arange(81) // 9, jnp.arange(81) % 9], -1)
    ids = jnp.arange(9)
    dist = jnp.abs(pos[:, None, :] - pos[None, :, :]).sum(-1)
    adjacent = dist == 1
    keep = ids[:, None] != ids[None, :]
    reach = adjacent[None,:,:] & keep[:,:,None] & keep[:,None,:]
    reach = reach | jnp.eye(9,dtype=jnp.bool_)[None,:,:]
    def closure(k, reach):
        return reach | (reach[:,:,k,None] & reach[:,None,k,:])
    reach = jax.lax.fori_loop(0,9,closure,reach)
    target_dist = jnp.abs(cells[:,None,:] - pos[None,:,:]).sum(-1)
    neighbors = (target_dist == 1)[None,:,:] & keep[:,None,:]
    covered = jnp.einsum('rxj,rjk->rxk', neighbors.astype(jnp.float32), reach.astype(jnp.float32)) > 0
    valid = jnp.all(covered | (~keep[:,None,:]), -1)
    valid = valid & (~jnp.any(target_dist == 0,-1))[None,:] & (~locks[:,None])
    return valid, target_dist


def agent_act(obs, reset, memory, rng):
    COLORS = jnp.asarray(COLOR_DATA, jnp.int32)
    SAME = (COLORS[:, :, None] == COLORS[:, None, :]).astype(jnp.float32)
    CELLS = jnp.stack([jnp.arange(81) // 9, jnp.arange(81) % 9], -1)
    memory = jax.tree.map(lambda old, new: jnp.where(reset, new, old), memory, init_agent())
    f = obs.node_features
    pos = obs.positions
    legal = obs.legal_actions
    step = f[0, 11]
    active = f[0, 10] > 0
    dist = jnp.abs(pos[:, None, :] - pos[None, :, :]).sum(-1)
    adj = (dist == 1).astype(jnp.float32)
    olddist = jnp.abs(memory['positions'][:,None,:] - memory['positions'][None,:,:]).sum(-1)
    change = adj - (olddist == 1).astype(jnp.float32)
    partner_seen = f[:9,9].astype(jnp.float32)
    evidence = jnp.einsum('ij,sij->s', change * partner_seen[:,None] * partner_seen[None,:], SAME) / 2
    updated = memory['motion'] + 2.0 * evidence
    updated = jnp.clip(updated - jnp.max(updated), -12., 0.)
    motion = jnp.where((~active) & (step == 3) & (~reset), updated, memory['motion'])
    known, weights, probs, pair = beliefs(obs, memory['known'], motion)
    same_edges = jnp.einsum('ij,sij->s', adj, SAME) / 2
    success = jnp.sum(weights * (same_edges >= 5.99))
    entropy = -jnp.sum(probs * jnp.log(jnp.maximum(probs, 1e-12)), -1)
    def observe_choice(_):
        can_move, target_dist = geometry(pos, f[:9,8] > 0)
        onehot = jax.nn.one_hot(COLORS, 3)
        joint = jnp.einsum('s,suc,sij->ucij', weights, onehot, SAME)
        conditional_pair = joint / jnp.maximum(probs[:,:,None,None],1e-9)
        offdiag = 1 - jnp.eye(9)
        conditional_pair = conditional_pair * offdiag[None,None,:,:]
        edge_value = (target_dist == 1).astype(jnp.float32) - .055 * target_dist
        old_value = adj - .055 * dist
        delta = jnp.einsum('xj,ucij->ucix',edge_value,conditional_pair) - jnp.sum(old_value[None,None,:,:] * conditional_pair,-1)[:,:,:,None]
        delta += .012 * (jnp.einsum('xj,ij->ix',(target_dist == 1).astype(jnp.float32),offdiag)-adj.sum(-1)[:,None])[None,None,:,:]
        best_delta = jnp.max(jnp.where(can_move[None,None,:,:],delta,-1e6),(-2,-1))
        score = jnp.sum(probs * best_delta,-1) + .12 * entropy
        score -= .0001 * jnp.arange(9)
        return 1 + jnp.argmax(jnp.where(legal[1:10],score,-1e9))
    observe = jax.lax.cond(step < 2, observe_choice, lambda _: jnp.asarray(1,jnp.int32), None)

    def move(_):
        offdiag = 1 - jnp.eye(9)
        def changes(board):
            d = jnp.abs(board[:,None,:] - board[None,:,:]).sum(-1)
            targets = jnp.abs(CELLS[:,None,:] - board[None,:,:]).sum(-1)
            edge_value = (targets == 1).astype(jnp.float32) - .055 * targets
            old_value = (d == 1).astype(jnp.float32) - .055 * d
            delta = jnp.einsum('xj,ij->ix',edge_value,pair*offdiag) - jnp.sum(old_value*pair*offdiag,-1)[:,None]
            delta += .012 * (jnp.einsum('xj,ij->ix',(targets == 1).astype(jnp.float32),offdiag) - (d == 1).sum(-1)[:,None])
            return delta
        delta = changes(pos)
        values, indices = jax.lax.top_k(jnp.where(legal[10:739],delta.reshape(-1),-1e9),8)
        boards = jnp.broadcast_to(pos,(8,9,2)).at[jnp.arange(8),indices//81,:].set(CELLS[indices%81])
        def future(board):
            valid, _ = geometry(board,f[:9,8] > 0)
            return jnp.maximum(0.,jnp.max(jnp.where(valid,changes(board),-1e9)))
        next_gain = jax.vmap(future)(boards)
        nextadj = (jnp.abs(boards[:,:,None,:] - boards[:,None,:,:]).sum(-1) == 1).astype(jnp.float32)
        count = jnp.einsum('kij,sij->ks',nextadj,SAME) / 2
        completion = jnp.sum((count > 5.99) * weights[None,:],-1)
        remaining = 8 - jnp.sum(jnp.any(f[9:,3:6] > 0,-1)) - jnp.sum(f[9:,8])
        score = values + .65 * next_gain * (remaining > 1) + .7 * completion
        return 10 + indices[jnp.argmax(score)]

    def hint(_):
        hset = f[9:,3:6].astype(jnp.float32)
        match = jnp.einsum('hc,ic->hi', hset, probs)
        neighbors = jnp.sum(adj * pair, -1)
        # Lock well-connected, confidently matching cards.
        score = 10 * match + .7 * neighbors[None, :] + .06 * adj.sum(-1)[None,:]
        score += .05 * (3 - hset.sum(-1))[:,None]
        score += .25 * (2 - hset.sum(-1))[:,None] * (1 - f[:9,9])[None,:]
        occupied = jnp.all(CELLS[:,None,:] == pos[None,:,:], -1)
        place_score = jnp.einsum('hi,xi->hx', score, occupied.astype(jnp.float32))
        place_action = 743 + jnp.argmax(jnp.where(legal[743:1067].reshape(4,81), place_score, -1e9))
        reveal_action = 739 + jnp.argmax(legal[739:743])
        safe = (match > .99) & (neighbors[None,:] > .9)
        safe_cells = jnp.einsum('hi,xi->hx',safe.astype(jnp.float32),occupied.astype(jnp.float32)) > .5
        safe_legal = safe_cells & legal[743:1067].reshape(4,81)
        early_action = 743 + jnp.argmax(jnp.where(safe_legal, place_score, -1e9))
        return jnp.where(jnp.any(safe_legal), early_action, jnp.where(jnp.any(legal[739:743]), reveal_action, place_action))

    action = jax.lax.cond(step == 2, move, lambda _: jax.lax.cond(step == 3, hint, lambda _: observe, None), None)
    revealed = jnp.any(f[9:,3:6] > 0, -1)
    placed = f[9:,8] > 0
    value = jnp.sum(jnp.where(placed, 1., jnp.where(revealed, 2., 5.)))
    stop = (success > .95) | ((success > .6) & (success * value > 4.2))
    action = jnp.where((step == 0) & stop, 1067, action)
    action = jnp.where(active, action, 0).astype(jnp.int32)
    return action, {'known': known, 'positions': pos, 'motion': motion}, {'known':known, 'probs':probs, 'success':success}
